import React from 'react';

import OneArticleBody from '@apps/Articles/components/OneArticleBody';
import { IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';
import { IHikingScheduleResult } from '@apps/Hiking/@types/hikingScheduleResults.types';

import ScheduleItem from '../ScheduleItem';
import ScheduleResultStatus from '../ScheduleResultStatus';

export interface IScheduleResultPreviewModalProps {
  scheduleItem: IHikingScheduleItem;
  scheduleResult: IHikingScheduleResult;
}

const ScheduleResultPreviewModal: React.FC<IScheduleResultPreviewModalProps> = ({
  scheduleItem,
  scheduleResult,
}) => {
  return (
    <section>
      <h5>Оригинальный пункт плана</h5>
      <ScheduleItem scheduleItem={scheduleItem} />
      <h5>
        Результат <ScheduleResultStatus status={scheduleResult.status} />
      </h5>
      <div>
        {scheduleResult.d1 && `с ${scheduleResult.d1.toLocaleString()}`}
        {scheduleResult.d2 && ` до ${scheduleResult.d2.toLocaleString()}`}
      </div>
      {scheduleResult.name.length > 0 && <h6>{scheduleResult.name}</h6>}
      <OneArticleBody text={scheduleResult.text} />
    </section>
  );
};

export default ScheduleResultPreviewModal;
