import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapHikingScheduleResult,
  mapHikingScheduleResultToAddDTO,
  mapHikingScheduleResultToUpdateDTO,
} from '../@mappers/hikingScheduleResults.mapper';
import { IHikingScheduleResultDTO } from '../@types/DTO/hikingScheduleResults.dto.types';
import { IHikingScheduleResult } from '../@types/hikingScheduleResults.types';

export const getHikingScheduleResults = async (id_hiking: number) => {
  const res = await get('/ajax/hiking/shedule_result_list.php', { id_hiking }).then<
    IHikingScheduleResultDTO[]
  >(handleApiError);
  return res.map(mapHikingScheduleResult);
};

export const addHikingScheduleResult = async (
  result: IHikingScheduleResult,
): Promise<IHikingScheduleResult> => {
  const data = mapHikingScheduleResultToAddDTO(result);
  const res = await post('/ajax/hiking/shedule_result_add.php', data).then<{ id: number }>(
    handleApiError,
  );
  return { ...result, id: +res.id };
};

export const updateHikingScheduleResult = async (result: IHikingScheduleResult) => {
  const data = mapHikingScheduleResultToUpdateDTO(result);
  await post('/ajax/hiking/shedule_result_edit.php', data).then<{ success: boolean }>(
    handleApiError,
  );
  return result;
};
export const deleteHikingScheduleResult = async (id: number) => {
  const res = await post('/ajax/hiking/shedule_result_del.php', {
    id,
  }).then<{ success: boolean }>(handleApiError);
  return res.success;
};
