import { getSQLDate } from '@helpers/dateHelper';

import {
  HikingScheduleResultStatus,
  IHikingScheduleResultDTO,
  IHikingScheduleResultUpdateDTO,
} from '../@types/DTO/hikingScheduleResults.dto.types';
import { IHikingScheduleResult } from '../@types/hikingScheduleResults.types';
import { IHikingScheduleResultAddDTO } from './../@types/DTO/hikingScheduleResults.dto.types';

export const mapHikingScheduleResult = (
  backData: IHikingScheduleResultDTO,
): IHikingScheduleResult => {
  return {
    id: +backData.id,
    name: backData.name,
    id_hiking_schedule: +backData.id_hiking_schedule,
    id_hiking_schedule_related: backData.id_hiking_schedule_related
      ? +backData.id_hiking_schedule_related
      : null,

    d1: backData.d1 ? new Date(backData.d1) : null,
    d2: backData.d2 ? new Date(backData.d2) : null,

    status: backData.status,
    text: backData.text,

    created_at: new Date(backData.created_at),
    updated_at: backData.updated_at ? new Date(backData.updated_at) : null,
    id_author: +backData.id_author,
  };
};

export const mapHikingScheduleResultToAddDTO = (
  data: IHikingScheduleResult,
): IHikingScheduleResultAddDTO => {
  return {
    id_hiking_schedule: data.id_hiking_schedule,
    id_hiking_schedule_related: data.id_hiking_schedule_related,
    d1: data.d1 ? getSQLDate(data.d1) : null,
    d2: data.d2 ? getSQLDate(data.d2) : null,
    name: data.name,
    text: data.text,
    status: data.status,
  };
};

export const mapHikingScheduleResultToUpdateDTO = (
  data: IHikingScheduleResult,
): IHikingScheduleResultUpdateDTO => {
  return { ...mapHikingScheduleResultToAddDTO(data), id: data.id };
};

export const getEmptyScheduleResult = (
  id_hiking_schedule: number,
  data: Partial<IHikingScheduleResult>,
): IHikingScheduleResult => {
  return {
    id: 0,
    id_hiking_schedule,
    id_hiking_schedule_related: null,
    d1: null,
    d2: null,
    name: '',
    status: HikingScheduleResultStatus.completed,
    text: '',

    created_at: new Date(),
    updated_at: null,
    id_author: 0,

    ...data,
  };
};
