import React, { JSX } from 'react';

import ArrowLeftRight from '@pohodnik/icons/svg/Arrows/ArrowLeftRight';
import Calendar4Week from '@pohodnik/icons/svg/DateTime/Calendar4Week';
import CalendarCheck from '@pohodnik/icons/svg/DateTime/CalendarCheck';
import CalendarX from '@pohodnik/icons/svg/DateTime/CalendarX';
import SkipForwardCircle from '@pohodnik/icons/svg/Media/SkipForwardCircle';
import clsx from 'clsx';

import { HikingScheduleResultStatus } from '@apps/Hiking/@types/DTO/hikingScheduleResults.dto.types';
interface IScheduleResultStatusProps extends React.HTMLAttributes<HTMLSpanElement> {
  status: HikingScheduleResultStatus;
}

export const hikingScheduleResultStatusNames: Record<HikingScheduleResultStatus, string> = {
  [HikingScheduleResultStatus.completed]: 'Выполнено',
  [HikingScheduleResultStatus.failed]: 'Не выполнено',
  [HikingScheduleResultStatus.rescheduled]: 'Перепланировано',
  [HikingScheduleResultStatus.skipped]: 'Пропущено',
  [HikingScheduleResultStatus.swapped]: 'Перенесено',
} as const;
const hikingScheduleResultStatusColors: Record<HikingScheduleResultStatus, string> = {
  [HikingScheduleResultStatus.completed]: 'text-success',
  [HikingScheduleResultStatus.failed]: 'text-danger',
  [HikingScheduleResultStatus.rescheduled]: 'text-info',
  [HikingScheduleResultStatus.skipped]: 'text-warning',
  [HikingScheduleResultStatus.swapped]: 'text-info',
} as const;
const hikingScheduleResultStatusIcons: Record<HikingScheduleResultStatus, JSX.Element> = {
  [HikingScheduleResultStatus.completed]: <CalendarCheck />,
  [HikingScheduleResultStatus.failed]: <CalendarX />,
  [HikingScheduleResultStatus.rescheduled]: <Calendar4Week />,
  [HikingScheduleResultStatus.skipped]: <SkipForwardCircle />,
  [HikingScheduleResultStatus.swapped]: <ArrowLeftRight />,
} as const;

const ScheduleResultStatus = ({ status, className, ...rest }: IScheduleResultStatusProps) => {
  return (
    <span
      {...rest}
      title={hikingScheduleResultStatusNames[status]}
      className={clsx(className, hikingScheduleResultStatusColors[status])}
    >
      {hikingScheduleResultStatusIcons[status]}
    </span>
  );
};

export default ScheduleResultStatus;
